output_text:
[
  {
    "id": "cart_check_in_at_depot",
    "text": "A shopper is obliged to check out a cart from the cart depot before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "cart_depot": "at(1,5)",
        "depot_cart_present": "cartAt(1,5)"
      },
      "events": {
        "take_cart_from_depot": {
          "pre": {
            "and": [
              "cart_depot",
              "depot_cart_present",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart_from_depot"
    }
  },
  {
    "id": "no_bypass_depot_cart",
    "text": "A shopper at the cart depot while a cart is available there is prohibited from moving away without taking the cart.",
    "abstraction": {
      "state_properties": {
        "cart_depot": "at(1,5)",
        "depot_cart_present": "cartAt(1,5)",
        "waiting_at_cart_depot": {
          "and": [
            "cart_depot",
            "depot_cart_present"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "waiting_at_cart_depot",
          "MOVE"
        ]
      }
    }
  },
  {
    "id": "items_must_be_collected_with_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they currently have the shopping cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_possession": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "no_hand_carrying_merchandise",
    "text": "A shopper is prohibited from carrying merchandise by hand instead of keeping it in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "cart_available_to_carry_goods": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_after_taking_it",
    "text": "After taking a cart, the shopper is obliged to return it at the designated return bay before the trip ends.",
    "abstraction": {
      "state_properties": {
        "cart_depot": "at(1,5)",
        "cart_return_bay": "at(0,1)",
        "cart_returned_at_bay": "cartAt(0,1)"
      },
      "events": {
        "take_cart_from_depot": {
          "pre": {
            "and": [
              "cart_depot",
              "cartAt(1,5)",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_at_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart_from_depot",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "only_leave_cart_at_return_bay",
    "text": "A shopper is prohibited from leaving a cart anywhere except the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "away_from_return_bay": {
          "not": "cart_return_bay"
        }
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "away_from_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "exit_only_after_cart_return",
    "text": "A shopper is prohibited from exiting the store while still having the cart or before the cart is parked at the return bay.",
    "abstraction": {
      "state_properties": {
        "exit_cell": "at(9,5)",
        "cart_returned_at_bay": "cartAt(0,1)",
        "bad_exit_cart_status": {
          "or": [
            "hasCart",
            {
              "not": "cart_returned_at_bay"
            }
          ]
        }
      },
      "events": {
        "exit_store": {
          "pre": {
            "and": [
              "exit_cell",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          "bad_exit_cart_status"
        ]
      }
    }
  },
  {
    "id": "cart_free_exit_concourse",
    "text": "The final exit concourse is a pedestrian-only area where shoppers are prohibited from pushing carts.",
    "abstraction": {
      "state_properties": {
        "exit_concourse": {
          "or": [
            "at(8,2)",
            "at(9,2)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "pushing_cart": "hasCart",
        "cart_in_exit_concourse": {
          "and": [
            "pushing_cart",
            "exit_concourse"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_exit_concourse"
    }
  }
]
